(() => {
  const N = window.__noir, G = N.game, r = N.renderer;
  const R = window.__hr = { frames: [], t0: performance.now(), mark: {} };
  let last = performance.now();
  const info = () => ({ prog: (r.info.programs || []).length, geo: r.info.memory.geometries, tex: r.info.memory.textures });
  let prev = info();
  const tick = (now) => {
    const dt = now - last; last = now;
    const cur = info();
    const S = G.city && G.city.stream ? G.city.stream.stats : null;
    const row = { t: +((now - R.t0) / 1000).toFixed(2), dt: +dt.toFixed(1), dprog: cur.prog - prev.prog, dgeo: cur.geo - prev.geo, dtex: cur.tex - prev.tex, built: S ? S.built : 0, sms: S ? +S.lastMs.toFixed(1) : 0, v: G.city && G.city.car ? +(G.city.car.speed * 3.6).toFixed(0) : 0 };
    prev = cur;
    R.frames.push(row);
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
  return 1;
})()

(() => {
  const G = window.__noir.game, R = G.city, T = window.__ht = {};
  const w = (o, k, name) => { const f = o[k].bind(o); o[k] = (...a) => { const t = performance.now(); const r = f(...a); T[name] = (T[name] || 0) + performance.now() - t; return r; }; };
  w(R.cabin, 'attach', 'cabin.attach'); w(G.vehicles, 'setPlayer', 'setPlayer'); w(G.sfx, 'play', 'sfx.play'); w(R.cabin.screen, 'attach', 'screen.attach');
  w(G.player.hands, 'equip', 'hands.equip'); w(G.controller, 'setMode', 'setMode');
  const pl = window.__noir.pipeline; if (pl && pl.render) w(pl, 'render', 'render');
  return 1;
})()
